1→"""Count words and lines from standard input."""

from __future__ import annotations

import re
import sys

HELP = "Usage: textstats [--top N]  # read stdin, print word and line counts; with --top N also print the N most frequent words\n"

10→
def count_words(text: str) -> int:
    return len(text.split())


def count_lines(text: str) -> int:
    if text == "":
        return 0
    return text.count("\n") + (0 if text.endswith("\n") else 1)

20→
def _is_top_n(token: str) -> bool:
    return re.fullmatch(r"[1-9][0-9]*", token) is not None


def _ranked(text: str, limit: int) -> list[tuple[str, int]]:
    counts: dict[str, int] = {}
    for word in text.split():
        counts[word] = counts.get(word, 0) + 1
    # Higher frequency first; equal frequencies use ascending code-point order.
30→    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["--help"]:
        sys.stdout.write(HELP)
        return 0
    limit: int | None = None
40→    if len(args) == 2 and args[0] == "--top" and _is_top_n(args[1]):
        limit = int(args[1])
    elif args:
        sys.stderr.write(HELP)
        return 2
    data = sys.stdin.read()
    sys.stdout.write(f"words: {count_words(data)}\nlines: {count_lines(data)}\n")
    if limit is not None:
        for word, freq in _ranked(data, limit):
            sys.stdout.write(f"{word} {freq}\n")
50→    return 0


if __name__ == "__main__":
    raise SystemExit(main())
